  {
    "pattern": "UnicodeEncodeError: 'gbk' codec can't encode character '\\u2713' in position",
    "fix": "When printing Unicode characters like ✓ (\\u2713) to console on Windows with GBK encoding, use .encode('utf-8').decode('gbk', 'ignore') or set PYTHONIOENCODING=utf-8, or replace Unicode symbols with ASCII alternatives like [OK].",
    "source": "AUTONOMOUS_REPORT.md — Task 1/28 [CRASHED]"
  },
  {
    "pattern": "LLM API error 400: 'An assistant message with tool_calls must be followed by tool messages responding to each tool_call_id'",
    "fix": "After receiving tool_calls from the LLM, ensure every tool_call_id has a corresponding tool result message appended before the next LLM call. Collect all tool_calls in a batch, execute them, then append all tool result messages at once. Never call the LLM again without responding to all pending tool_call_ids.",
    "source": "AUTONOMOUS_REPORT.md — Tasks 2, 7, 11, 13, 14, 15, 17, 18, 19, 20, 22 (repeated error)"
  },
  {
    "pattern": "LLM API error 400: tool_call_id 'unknown' or missing tool_call_id",
    "fix": "DeepSeek API requires that each tool_call in an assistant message has a valid non-empty tool_call_id. If the model returns 'unknown' as the tool_call_id, the code must reject or regenerate that response. Validate tool_call_ids before sending to the API.",
    "source": "AUTONOMOUS_REPORT.md — Tasks 2, 7, 11, 13, 14, 15, 17, 18, 19, 20, 22"
  },
  {
    "pattern": "DeepSeek model chooses to describe tools in text instead of calling tool_calls in long context",
    "fix": "Shorten the system prompt to remove verbose descriptions. Use strict formatting rules like 'response must be ONLY tool_calls JSON'. Ensure task descriptions are concise and directive. This is a prompt alignment issue, not a code bug.",
    "source": "STATUS.md — 'Agent Loop prompt alignment' section"
  },
  {
    "pattern": "Code only processes the first tool_call when DeepSeek returns multiple tool_calls",
    "fix": "Iterate over all tool_calls in the response, collect them into a batch, execute all, and append all tool result messages before the next LLM call. Do not only handle calls[0].",
    "source": "AUTONOMOUS_REPORT.md — Phase 3: 'problem: DeepSeek returns multiple tool_calls but code only processes the first'"
  },
  {
    "pattern": "tools parameter not passed on every LLM call",
    "fix": "Pass the tools parameter on every LLM API call, not just the first one. Remove any 'tool role check' that might prevent tools from being sent.",
    "source": "AUTONOMOUS_REPORT.md — Phase 3: 'fix: every LLM call passes tools'"
  },
  {
    "pattern": "will_continue flag not handled, causing loop to terminate early",
    "fix": "Check the will_continue field in the LLM response. If it is true, continue the loop instead of ending. Implement a continue loop mechanism.",
    "source": "AUTONOMOUS_REPORT.md — Phase 3: 'will_continue not handled → continue loop'"
  },
  {
    "pattern": "DEEPSEEK_API_KEY fallback missing when environment variable not set",
    "fix": "Add a fallback mechanism for DEEPSEEK_API_KEY: check environment variable first, then fall back to a config file or hardcoded default. Ensure the key is always available before making API calls.",
    "source": "AUTONOMOUS_REPORT.md — Phase 3: 'DEEPSEEK_API_KEY fallback missing → fixed'"
  },
  {
    "pattern": "sandbox_exec tool not registered in TOOL_DEFINITIONS",
    "fix": "Add sandbox_exec to the TOOL_DEFINITIONS list so the LLM knows it can use this tool. Without registration, the model will never call it.",
    "source": "AUTONOMOUS_REPORT.md — Phase 4: 'Added sandbox_exec to TOOL_DEFINITIONS'"
  }
]
"}

